CREATE TABLE public.video_projects (id uuid PRIMARY KEY, user_id uuid NOT NULL, name text NOT NULL DEFAULT 'Projeto sem título', composition jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.video_projects TO authenticated;
GRANT ALL ON public.video_projects TO service_role;
ALTER TABLE public.video_projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner manages projects" ON public.video_projects FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.video_media (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES public.video_projects(id) ON DELETE CASCADE, user_id uuid NOT NULL, name text NOT NULL, path text NOT NULL, kind text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.video_media TO authenticated;
GRANT ALL ON public.video_media TO service_role;
ALTER TABLE public.video_media ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner manages media" ON public.video_media FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.video_projects p WHERE p.id = project_id AND p.user_id = auth.uid()));
CREATE TABLE public.video_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, project_id uuid NOT NULL REFERENCES public.video_projects(id) ON DELETE CASCADE, kind text NOT NULL, status text NOT NULL DEFAULT 'queued', progress real NOT NULL DEFAULT 0, provider_id text, result_path text, error text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.video_jobs TO authenticated;
GRANT ALL ON public.video_jobs TO service_role;
ALTER TABLE public.video_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner reads jobs" ON public.video_jobs FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY "Owner reads studio files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'studio-media' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Owner uploads studio files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'studio-media' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Owner updates studio files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'studio-media' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'studio-media' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Owner deletes studio files" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'studio-media' AND (storage.foldername(name))[1] = auth.uid()::text);